using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace FontFilter;
public sealed class AiAnalysisWindow:Window
{
 readonly List<(AiTagSuggestion Tag,CheckBox Box)> choices=new();
 public IEnumerable<string> SelectedTags=>choices.Where(x=>x.Box.IsChecked==true).Select(x=>x.Tag.Name);
 public AiAnalysisWindow(FontRecord font,ApiOptions options,string key){LightTheme.Apply(this);Title="AI辅助标注 · "+font.Family;Width=720;Height=650;MinWidth=560;MinHeight=450;WindowStartupLocation=WindowStartupLocation.CenterOwner;var cts=new CancellationTokenSource();
  var dock=new DockPanel{Margin=new Thickness(28)};Content=dock;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);dock.Children.Add(top);top.Children.Add(new TextBlock{Text="为字形，补充有依据的标签。",FontSize=23,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,10)});top.Children.Add(new TextBlock{Text=font.Label,Foreground=Brushes.DimGray,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,8)});top.Children.Add(new TextBlock{Text="将向 "+FontAiService.Endpoint(options.BaseUrl).Host+" 发送字体名称与已有介绍。\n这是文字资料分析；没有介绍时，无法可靠判断字形和气质。",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.Gray,LineHeight=22});
  var state=new TextBlock{Text="点击开始才会请求API，费用由你的API账户承担。",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.Gray,Margin=new Thickness(0,16,0,14)};top.Children.Add(state);var begin=new Button{Content="开始分析当前字体",Style=(Style)FindResource("PrimaryButton"),HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,0,0,18)};top.Children.Add(begin);
  var bottom=new DockPanel{Margin=new Thickness(0,20,0,0)};DockPanel.SetDock(bottom,Dock.Bottom);dock.Children.Add(bottom);bottom.Children.Add(new TextBlock{Text="候选标签默认不勾选，请核对依据后选择。",Foreground=Brushes.Gray,TextWrapping=TextWrapping.Wrap,VerticalAlignment=VerticalAlignment.Center});var apply=new Button{Content="确认选中标签",Style=(Style)FindResource("PrimaryButton"),IsEnabled=false,HorizontalAlignment=HorizontalAlignment.Right};bottom.Children.Add(apply);var body=new StackPanel();dock.Children.Add(new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});bool busy=false;
  begin.Click+=async(_,_)=>{if(busy)return;busy=true;begin.IsEnabled=false;body.Children.Clear();choices.Clear();apply.IsEnabled=false;state.Text="正在分析已有文字资料…";try{var result=await new FontAiService().AnalyzeAsync(options,key,font,cts.Token);if(cts.IsCancellationRequested)return;foreach(var tag in result.Tags){var card=new Border{Background=Brushes.White,CornerRadius=new CornerRadius(10),Padding=new Thickness(16),Margin=new Thickness(0,0,0,10)};var content=new StackPanel();card.Child=content;var box=new CheckBox{Content=tag.Name+"   ·   "+tag.Confidence.ToString("P0"),FontSize=15,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,10)};content.Children.Add(box);content.Children.Add(new TextBlock{Text="依据："+tag.Evidence,TextWrapping=TextWrapping.Wrap,Foreground=new SolidColorBrush(Color.FromRgb(83,117,91)),LineHeight=22});content.Children.Add(new TextBlock{Text=tag.Reason,TextWrapping=TextWrapping.Wrap,Foreground=Brushes.Gray,Margin=new Thickness(0,5,0,0)});choices.Add((tag,box));box.Checked+=(_,_)=>apply.IsEnabled=SelectedTags.Any();box.Unchecked+=(_,_)=>apply.IsEnabled=SelectedTags.Any();body.Children.Add(card);}state.Text=(result.Tags.Count==0?"未找到有足够资料依据的标签。可先补充官网介绍。":$"已返回{result.Tags.Count}个候选标签；请核对后勾选。")+(result.Note.Length>0?"\n"+result.Note:"");}catch(OperationCanceledException){if(!cts.IsCancellationRequested)state.Text="请求超时。可检查服务状态后重新分析。";}catch(Exception ex){if(!cts.IsCancellationRequested)state.Text=ex is System.Text.Json.JsonException?"返回内容不是有效JSON，可检查JSON模式与模型设置。":"分析失败："+ex.Message;}finally{busy=false;begin.IsEnabled=true;}};
  apply.Click+=(_,_)=>{if(SelectedTags.Any())DialogResult=true;};Closed+=(_,_)=>cts.Cancel();
 }
}
